package com.kavi.kavimart.filter;
import javax.servlet.*;import javax.servlet.http.*;import java.io.IOException;import java.util.UUID;import org.slf4j.MDC;import org.slf4j.Logger;import org.slf4j.LoggerFactory;
/** Adds a per-request correlation ID to logs and the response. */
public class LoggingFilter implements Filter {private static final Logger LOG=LoggerFactory.getLogger(LoggingFilter.class);/** {@inheritDoc} */ public void doFilter(ServletRequest request,ServletResponse response,FilterChain chain)throws IOException,ServletException{String id=UUID.randomUUID().toString();MDC.put("requestId",id);if(response instanceof HttpServletResponse http)http.setHeader("X-Request-ID",id);long start=System.nanoTime();try{chain.doFilter(request,response);}finally{long duration=(System.nanoTime()-start)/1_000_000;String method=request instanceof HttpServletRequest h?h.getMethod():"";String uri=request instanceof HttpServletRequest h?h.getRequestURI():"";LOG.info("{} {} completed in {}ms",method,uri,duration);MDC.remove("requestId");}}}
